// Generated from the local synthetic tone fixtures; see README.md.
export const encodedAudio = {
  "tone.mp3":
    "",
  "tone.flac":
    "",
  "tone.wav":
    "",
} as const;
export function audioBytes(name: keyof typeof encodedAudio) {
  return Uint8Array.from(atob(encodedAudio[name]), (c) => c.charCodeAt(0));
}
